import { readFileSync } from 'node:fs';
const load = (name) => JSON.parse(readFileSync(new URL(`./food-curation/data/${name}`, import.meta.url), 'utf8'));
const activation = load('prepared-food-production-activation.v1.json');
const calculations = [...load('batch-1.calculations.v10.json').calculations, ...load('batch-1.calculations.v11.json').calculations];
const semantics = {
    CP_CHAPATI: { roles: ['BREAD', 'STARCH'], mealHeads: ['BREAKFAST', 'LUNCH', 'DINNER'], family: 'WHEAT_BREAD', category: 'grain', serving: '1 Chapati', multipliers: [1, 2, 3] },
    CP_BHINDI_SABJI: { roles: ['VEGETABLE'], mealHeads: ['LUNCH', 'DINNER'], family: 'OKRA', category: 'vegetable', serving: '1 katori Bhindi Sabji', multipliers: [.5, 1, 1.5, 2] },
    CP_BHINDI_ALOO: { roles: ['VEGETABLE', 'STARCH'], mealHeads: ['LUNCH', 'DINNER'], family: 'OKRA_POTATO', category: 'vegetable', serving: '1 katori Bhindi Aloo', multipliers: [.5, 1, 1.5] }
};
export function createProductionPreparedFoods() { return activation.records.map(record => { const release = load(record.sourceValidationReference); const calc = calculations.find(x => x.recipeId === release.recipeId), semantic = semantics[release.recipeId]; if (record.newState !== 'PRODUCTION_ACTIVE' || record.previousState !== 'NOT_PRODUCTION_ACTIVE' || release.productionActivationStatus !== record.previousState || release.releaseStatus !== 'VALIDATED_RELEASED' || release.validationReleaseId !== record.releaseId || release.releaseHash !== record.immutableArtifactHash || release.calculationHash !== calc?.calculationHash || !record.auditEventId || !semantic)
    throw new Error(`INVALID_PREPARED_FOOD_ACTIVATION:${record.releaseId}`); const n = calc.per100gNutrition; if (!Object.values(n).every(Number.isFinite))
    throw new Error(`INVALID_PREPARED_FOOD_NUTRITION:${record.releaseId}`); return { id: `PF_${record.releaseId}`, version: release.validationReleaseVersion, canonicalCode: release.recipeId, canonicalName: release.recipeName.toLowerCase(), displayName: release.recipeName, foodType: 'VALIDATED_RECIPE', family: semantic.family, category: semantic.category, countryContext: 'INDIA', isIndianSpecificFood: true, sourcePolicyClass: 'INDIA_AUTHORITATIVE', sourceMappingId: `VALIDATION_RELEASE:${record.releaseId}:${record.immutableArtifactHash}`, sourceVersion: String(activation.activationVersion), vegetarianClass: 'VEGAN', dietTags: ['vegan', 'indian'], allergens: release.recipeId === 'CP_CHAPATI' ? ['gluten'] : [], intolerances: [], clinicalTags: [], avoidTags: release.recipeId === 'CP_BHINDI_ALOO' ? ['potato'] : [], mealHeads: semantic.mealHeads, roles: semantic.roles, nutrientsPer100g: { kcal: n.energyKcal, protein: n.proteinG, carbohydrate: n.carbohydrateG, fat: n.fatG, fibre: n.fibreG }, servings: [{ id: `SV_${record.releaseId}_V1`, version: 1, label: semantic.serving, grams: calc.servingGrams, millilitres: null, unit: release.recipeId === 'CP_CHAPATI' ? 'piece' : 'katori', isDefault: true, minMultiplier: Math.min(...semantic.multipliers), maxMultiplier: Math.max(...semantic.multipliers), allowedMultipliers: semantic.multipliers, active: true }], active: true, clientConsumable: true, generatorEligible: true, aliases: [release.recipeName.toLowerCase()] }; }); }
